from PIL import Image
import numpy as np
from collections import deque
im=np.array(Image.open('/app/runs/call_04/last/robot_r1:zed_link:Camera:0.jpg').convert('HSV'))
h,s,v=im.transpose(2,0,1)
mask=((h<12)|(h>245))&(s>100)&(v>70)
H,W=mask.shape; seen=np.zeros_like(mask); out=[]
for y in range(H):
 for x in range(W):
  if not mask[y,x] or seen[y,x]:continue
  q=[(y,x)];seen[y,x]=1; pts=[]
  while q:
   a,b=q.pop();pts.append((a,b))
   for aa,bb in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
    if 0<=aa<H and 0<=bb<W and mask[aa,bb] and not seen[aa,bb]:seen[aa,bb]=1;q.append((aa,bb))
  if len(pts)>2:
   ys=[p[0] for p in pts];xs=[p[1] for p in pts];out.append((len(pts),min(xs),max(xs),min(ys),max(ys)))
print(sorted(out,reverse=True)[:20])
